  if tg_op in ('UPDATE','DELETE') then raise exception 'Logistics booking request events are immutable and cannot be changed.'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_logistics_booking_request_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not public.is_trusted_logistics_booking_request_write() then raise exception 'Logistics booking requests are managed through trusted RPCs.'; end if;
  if tg_op = 'DELETE' then raise exception 'Logistics booking requests cannot be deleted.'; end if;
  new.updated_at := now(); return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_purchase_order_decision_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  po_record public.purchase_orders%rowtype;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    raise exception 'Purchase order decisions are immutable.';
  end if;

  if not public.is_trusted_purchase_order_decision_write() then
    raise exception 'Purchase order decisions must be created by trusted manufacturer decision flows.';
  end if;

  select * into po_record
  from public.purchase_orders
  where id = new.purchase_order_id;

  if not found then
    raise exception 'Purchase order does not exist.';
  end if;

  new.review_round := po_record.review_round;
  new.manufacturer_id := po_record.manufacturer_id;
  new.actor_profile_id := auth.uid();
  new.reason := nullif(btrim(coalesce(new.reason, '')), '');
  new.created_at := now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_purchase_order_item_write()
