 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_trusted_purchase_order_write() then
    return coalesce(new, old);
  end if;

  raise exception 'Purchase order items are immutable.';
end;
$function$

